// WordprocessingML `word/styles.xml` part for DOCX files generated by the
// formal-report export route (`src/app/api/database/patients/formal-report/export/route.js`).
//
// Kept in `src/lib` so the paragraph defaults can be unit tested without booting Next.
//
// The converter emits bare `<w:p>` / `<w:r>` elements (no `w:pPr` / `w:rPr`), so both the
// paragraph spacing and the font have to come from `w:docDefaults`:
// - without paragraph spacing Word applies zero space before/after, so consecutive report
//   paragraphs render on adjacent lines with no visible gap even though the source markdown
//   separated them with a blank line ("new paragraph spacing" disappearing on DOCX export);
// - without `rFonts`/`sz` the document renders in whatever the reader's Word default is
//   (Calibri 11, Aptos 12, ...), so the same report looks different on different machines.
//
// The package has no `theme1.xml` or `fontTable.xml`, so the explicit `rFonts` below is what
// Word actually uses everywhere: body text, headings, table cells and the TAC heading bars.
//
// Every value here comes from `reportPageMetrics`, which the A4 preview paginator also reads, so
// the page the planner sees on screen and the page Word prints break at the same place.
//
// Every other paragraph shape the converter emits already carries explicit spacing
// (headings, lists, block quotes, code blocks, table spacers) or is explicitly reset to
// zero here (table cell paragraphs, which must stay tight).

import {
    REPORT_BODY_FONT_FAMILY,
    REPORT_BODY_FONT_SIZE_HALF_POINTS,
    REPORT_BODY_LINE_TWIPS,
    REPORT_BODY_SPACE_AFTER_TWIPS,
    REPORT_BODY_SPACE_BEFORE_TWIPS,
    REPORT_HEADING_RULE,
    REPORT_HEADING_SCALE,
    REPORT_PAGE_HEIGHT_TWIPS,
    REPORT_PAGE_MARGIN_TWIPS,
    REPORT_PAGE_WIDTH_TWIPS,
} from './reportPageMetrics.js'

// Word's own default body spacing is 160 twips (8pt) after. The shared metrics use 120 twips (6pt),
// which is a full blank line between paragraphs; the 200 twips this used to carry read as
// double-spaced once combined with the 18pt document grid, and 120 (6pt) read as set solid.
export const WORD_BODY_SPACING_AFTER_TWIPS = REPORT_BODY_SPACE_AFTER_TWIPS

// 280 twips is 14pt leading, matching the preview's line height exactly. Without an explicit
// `w:line`, body text snapped to the document grid and rendered at 18pt.
export const WORD_BODY_LINE_TWIPS = REPORT_BODY_LINE_TWIPS
export const WORD_DOCUMENT_GRID_LINE_PITCH_TWIPS = REPORT_BODY_LINE_TWIPS

export const WORD_BODY_FONT_FAMILY = REPORT_BODY_FONT_FAMILY

// Word measures font size in half-points: 24 = 12pt.
export const WORD_BODY_FONT_SIZE_HALF_POINTS = REPORT_BODY_FONT_SIZE_HALF_POINTS

// A4, so the exported page is the page the preview laid out rather than US Letter.
export const WORD_PAGE_WIDTH_TWIPS = REPORT_PAGE_WIDTH_TWIPS
export const WORD_PAGE_HEIGHT_TWIPS = REPORT_PAGE_HEIGHT_TWIPS
export const WORD_PAGE_MARGIN_TWIPS = REPORT_PAGE_MARGIN_TWIPS

export const WORD_HEADING_COLORS = {
    level1: REPORT_HEADING_SCALE[0].color,
    level2: REPORT_HEADING_SCALE[1].color,
    level3: REPORT_HEADING_SCALE[2].color,
}

function buildHeadingStyleXml({ level, sizeHalfPoints, lineTwips, beforeTwips, afterTwips, color }) {
    // Headings set their own absolute leading: an 18pt heading inherits the body's 13.5pt line and
    // would be clipped by `w:lineRule="exact"`.
    const rule = level === REPORT_HEADING_RULE.level
        ? `<w:pBdr><w:bottom w:val="single" w:sz="${REPORT_HEADING_RULE.sizeEighths}" w:space="${REPORT_HEADING_RULE.spacePoints}" w:color="${REPORT_HEADING_RULE.color}"/></w:pBdr>`
        : ''
    return `    <w:style w:type="paragraph" w:styleId="Heading${level}">
        <w:name w:val="heading ${level}"/>
        <w:basedOn w:val="Normal"/>
        <w:qFormat/>
        <w:rPr><w:b/><w:color w:val="${color}"/><w:sz w:val="${sizeHalfPoints}"/></w:rPr>
        <w:pPr>${rule}<w:spacing w:before="${beforeTwips}" w:after="${afterTwips}" w:line="${lineTwips}" w:lineRule="exact"/></w:pPr>
    </w:style>`
}

export function buildWordStylesXml() {
    return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
    <w:docDefaults>
        <w:rPrDefault>
            <w:rPr><w:rFonts w:ascii="${WORD_BODY_FONT_FAMILY}" w:hAnsi="${WORD_BODY_FONT_FAMILY}" w:cs="${WORD_BODY_FONT_FAMILY}" w:eastAsia="${WORD_BODY_FONT_FAMILY}"/><w:sz w:val="${WORD_BODY_FONT_SIZE_HALF_POINTS}"/><w:szCs w:val="${WORD_BODY_FONT_SIZE_HALF_POINTS}"/></w:rPr>
        </w:rPrDefault>
        <w:pPrDefault>
            <w:pPr><w:snapToGrid w:val="0"/><w:spacing w:before="${REPORT_BODY_SPACE_BEFORE_TWIPS}" w:after="${WORD_BODY_SPACING_AFTER_TWIPS}" w:line="${WORD_BODY_LINE_TWIPS}" w:lineRule="exact"/></w:pPr>
        </w:pPrDefault>
    </w:docDefaults>
    <w:style w:type="paragraph" w:default="1" w:styleId="Normal">
        <w:name w:val="Normal"/>
        <w:qFormat/>
    </w:style>
${REPORT_HEADING_SCALE.map(buildHeadingStyleXml).join('\n')}
</w:styles>`
}
